-- PT122-S2-Q15. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT122-S2-Q15$batch10$ AND q.stimulus=$batch10$The greater the number of people who regularly use a product, the greater the number whose health is potentially at risk due to that product. More people regularly use household maintenance products such as cleaning agents and lawn chemicals than regularly use prescription medicines. Therefore, it is even more important for such household products to be carefully tested to ensure their safety than it is for prescription medicines to be so tested.$batch10$ AND q.prompt=$batch10$Which one of the following principles, if valid, most helps to justify drawing the conclusion in the argument above?$batch10$ AND q.correct_choice=$batch10$C$batch10$) THEN RAISE EXCEPTION 'Question changed: PT122-S2-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT122-S2-Q15$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S2-Q15'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT122-S2-Q15$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Careful safety testing is even more important for household products than for prescription medicines.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$The more people regularly use a product, the more people's health it may put at risk. More people regularly use household maintenance products than prescription medicines.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The evidence ends with "more people at risk from household products." The conclusion is "more important to test household products." The principle has to link the two: more people at risk means testing matters more.$batch10$), (3, $batch10$Goal$batch10$, $batch10$The more people whose health a product might put at risk, the more important it is to test that product.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT122-S2-Q15$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$"Depends mainly on" says the number of users is the key factor, but not which way it cuts. It doesn't say that more users make testing more important.$batch10$), ($batch10$B$batch10$, $batch10$This says testing is very important for widely used products. The conclusion compares household products with medicines, and this principle could make both equally important.$batch10$), ($batch10$C$batch10$, $batch10$Household products put more people at risk than prescription medicines. This principle says that makes testing them more important, which is the conclusion.$batch10$), ($batch10$D$batch10$, $batch10$This compares two medicines by dosing frequency. The argument compares household products with medicines by number of users.$batch10$), ($batch10$E$batch10$, $batch10$Household products do put more people at risk, so the "unless" clause is triggered. But all it does is cancel the rule that medicine testing is more important. That leaves household testing no less important than medicine testing. The conclusion needs it to be more important.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT122-S2-Q15$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
